<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  columns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # span 6 grid columns (out of 12)</span></span>
